import{_ as e,c as t,o as r,a2 as l}from"./chunks/framework.mqLGQ42V.js";const c=JSON.parse('{"title":"布局参数 (Parameters) - Rive 编辑器","description":"布局 (Layouts) 布局参数大致可以分为两类：影响父布局的参数和影响子布局的参数。","frontmatter":{"title":"布局参数 (Parameters) - Rive 编辑器","description":"布局 (Layouts) 布局参数大致可以分为两类：影响父布局的参数和影响子布局的参数。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 布局, 布局参数"}]]},"headers":[],"relativePath":"editor/layouts/layout-parameters.md","filePath":"editor/layouts/layout-parameters.md","lastUpdated":1774867914000}'),o={name:"editor/layouts/layout-parameters.md"};function i(n,a,s,h,d,p){return r(),t("div",null,[...a[0]||(a[0]=[l('<p>布局 (Layouts)</p><h1 id="布局参数-parameters" tabindex="-1">布局参数 (Parameters) <a class="header-anchor" href="#布局参数-parameters" aria-label="Permalink to &quot;布局参数 (Parameters)&quot;">​</a></h1><p>布局参数大致可以分为两类：影响父布局的参数和影响子布局的参数。</p><p>在 Rive 中，请记住布局参数通常只影响其他布局容器。这通常会导致布局的嵌套以实现所需效果，但也为与 Rive 更自由的画布进行创意混合提供了机会。</p><hr><h2 id="​-绝对布局与相对布局" tabindex="-1"><a href="#absolute-vs-relative">​</a> 绝对布局与相对布局 <a class="header-anchor" href="#​-绝对布局与相对布局" aria-label="Permalink to &quot;[​](#absolute-vs-relative) 绝对布局与相对布局&quot;">​</a></h2><p>要控制行 (Row) 或列 (Column) 中子布局的流向，需要子布局为<strong>相对 (Relative)</strong> 模式。你可以在检查器右上角切换。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 模式切换 Pn)</p></blockquote><ul><li><strong>绝对布局 (Absolute)</strong>：在画板或父布局容器中定位自己。可以将 2 条或更多边缘固定 (Pinned) 到容器。</li><li><strong>相对布局 (Relative)</strong>：位置由父级定义。更改父级的 flex 属性将决定子布局的行为。</li></ul><h2 id="​-缩放类型" tabindex="-1"><a href="#scale-types">​</a> 缩放类型 <a class="header-anchor" href="#​-缩放类型" aria-label="Permalink to &quot;[​](#scale-types) 缩放类型&quot;">​</a></h2><p>布局的宽度和高度可以使用 3 种不同的缩放行为：</p><ul><li><strong>固定 (Fixed)</strong>：宽度或高度为固定值（点或百分比）。</li><li><strong>包裹 (Hug)</strong>：宽度/高度缩小以适应其子元素。例如，让布局包裹文本对象，随文本长度自动调整大小。</li><li><strong>填充 (Fill)</strong>：扩展宽度/高度以填满整个父布局或画板的可用空间。</li></ul><h2 id="​-尺寸约束" tabindex="-1"><a href="#size-constraints">​</a> 尺寸约束 <a class="header-anchor" href="#​-尺寸约束" aria-label="Permalink to &quot;[​](#size-constraints) 尺寸约束&quot;">​</a></h2><p>由于可以设置最小 (Min) 和最大 (Max) 宽度/高度。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 尺寸约束 Pn)</p></blockquote><h2 id="​-裁剪-clip" tabindex="-1"><a href="#clip">​</a> 裁剪 (Clip) <a class="header-anchor" href="#​-裁剪-clip" aria-label="Permalink to &quot;[​](#clip) 裁剪 (Clip)&quot;">​</a></h2><p>开启后会隐藏布局边界之外的所有子元素。</p><h2 id="​-位置-仅限绝对布局" tabindex="-1"><a href="#position-absolute-layouts-only">​</a> 位置 (仅限绝对布局) <a class="header-anchor" href="#​-位置-仅限绝对布局" aria-label="Permalink to &quot;[​](#position-absolute-layouts-only) 位置 (仅限绝对布局)&quot;">​</a></h2><p>绝对布局允许你将边缘固定 (Pin) 到容器。你可以设置至少 2 个固定边缘（一横一纵）。</p><h2 id="​-内边距-padding-与外边距-margin" tabindex="-1"><a href="#padding-and-margin">​</a> 内边距 (Padding) 与外边距 (Margin) <a class="header-anchor" href="#​-内边距-padding-与外边距-margin" aria-label="Permalink to &quot;[​](#padding-and-margin) 内边距 (Padding) 与外边距 (Margin)&quot;">​</a></h2><ul><li><strong>内边距 (Padding)</strong>：布局边界与相对子布局之间的内部空间。</li><li><strong>外边距 (Margin)</strong>：布局边界与父布局之间的外部空间。</li></ul><hr><h2 id="​-布局子项" tabindex="-1"><a href="#layout-children">​</a> 布局子项 <a class="header-anchor" href="#​-布局子项" aria-label="Permalink to &quot;[​](#layout-children) 布局子项&quot;">​</a></h2><p>布局的 flex 参数仅应用于其内部包含的其他布局。为了生成自动流向的行、列和网格，内容项目本身必须被包裹在额外的布局容器中。</p><h2 id="​-行-列" tabindex="-1"><a href="#row/column">​</a> 行/列 <a class="header-anchor" href="#​-行-列" aria-label="Permalink to &quot;[​](#row/column) 行/列&quot;">​</a></h2><ul><li><strong>行 (Row)</strong>：沿水平轴排列子项。</li><li><strong>列 (Column)</strong>：沿垂直轴排列子项。</li><li>支持反向排布 (Reverse)。</li></ul><h2 id="​-换行-wrap" tabindex="-1"><a href="#wrap">​</a> 换行 (Wrap) <a class="header-anchor" href="#​-换行-wrap" aria-label="Permalink to &quot;[​](#wrap) 换行 (Wrap)&quot;">​</a></h2><ul><li><strong>不换行 (No Wrap)</strong>：内容超出边界时继续延伸。</li><li><strong>换行 (Wrap)</strong>：内容到达边界时，下一个项目将放在下方或旁边。</li></ul><h2 id="​-对齐-alignment" tabindex="-1"><a href="#alignment">​</a> 对齐 (Alignment) <a class="header-anchor" href="#​-对齐-alignment" aria-label="Permalink to &quot;[​](#alignment) 对齐 (Alignment)&quot;">​</a></h2><p>在检查器的小窗口中选择对齐点。</p><h2 id="​-对齐方式-justify" tabindex="-1"><a href="#justify">​</a> 对齐方式 (Justify) <a class="header-anchor" href="#​-对齐方式-justify" aria-label="Permalink to &quot;[​](#justify) 对齐方式 (Justify)&quot;">​</a></h2><p>使内容填满可用空间。</p><h2 id="​-间距-gap" tabindex="-1"><a href="#gap">​</a> 间距 (Gap) <a class="header-anchor" href="#​-间距-gap" aria-label="Permalink to &quot;[​](#gap) 间距 (Gap)&quot;">​</a></h2><p>可以设置水平和垂直方向的间距。</p><p><a href="/docs/editor/layouts/layout-tools">工具 (Tools)</a><a href="https://help.rive.app/editor/layouts/layout-styles" target="_blank" rel="noreferrer">样式 (Styles)</a></p>',35)])])}const m=e(o,[["render",i]]);export{c as __pageData,m as default};
